import csv,gzip,json
from extract import BASE,SRC,DATA
def main():
 rows=list(csv.DictReader((DATA/'county-baselines.csv').open()));states=json.loads((BASE/'state-targets.json').read_text());settings=json.loads((BASE/'scenario-settings.json').read_text());controls=json.loads((SRC/'state-controls.json').read_text());news={r['id']:r for r in json.loads((SRC/'shared-news-receipts.json').read_text())};books={r['id']:r for r in json.loads((SRC/'peer-original-receipts.json').read_text())}
 def target(s,t='tie'):return next(x for x in states if x['scenario']==s and x['target']==t)
 body=['# South Dakota historical partisanship and conditional paths to win\n',
 'Observed **2026-10-19 UTC**. Complete historical coverage is **66 counties**, with **691 native presidential rows in2024, 687 native Senate rows in2022, and693 native Senate rows in2020**. These are source-specific reporting universes, not current precinct geometry. All units, including the entire nonpriority remainder, stay in state calculations. The current contest is **Brian L Bengs, Independent, versus Mike Rounds, Republican**; there is no current Democratic Senate choice in the inspected official publication ballot. Numerical historical Democratic outcomes below remain election-specific. Conditional named opposition scenarios do not relabel Bengs or treat every non-Republican as Democratic.\n',
 'The [current Lincoln County publication ballot](https://www.lincolncountysd.gov/DocumentCenter/View/1989/Sample-Ballot-2026-PDF), linked by the [county elections page](https://www.lincolncountysd.gov/159/Elections), states November3,2026 and lists Rounds Republican Party/Bengs Independent. Primary web inspection succeeded; direct original downloads returned404/empty, including alternate same-resource routes. The [retained web observation](data/baselines/source/lincoln-ballot-web-observation.txt) is labeled parsed evidence, not original PDF bytes. The separately retained [current SOS candidate list](https://vip.sdsos.gov/candidatelist.aspx?eid=774) has Bengs IND and Rounds REP active and Julian Beaudion DEM withdrawn August4. That current list is corroboration, not a primary nominee or a final vendor-ID map. The [official2026 precinct manual](https://sdsos.gov/elections-voting/assets/2026%20Documents/2026PrecinctManual.pdf), PDFp15, says write-in votes are not counted. No eligible ordinary write-in choice is invented; invalid-mark counts remain unavailable.\n',
 'Rounds is in [ClassII](https://www.senate.gov/senators/Class_II.htm), last regularly elected in2020; Thune is in [ClassIII](https://www.senate.gov/senators/Class_III.htm), elected in2022. Thus2020 Rounds–Ahlers is the **same seat**,2022 Thune–Bengs–Lesnar is the **other seat and actual midterm**, and2024 president is the recent statewide priority basis. There was no South Dakota Senate election in2024. General-election plurality under [SDCL12-20-39](https://sdlegislature.gov/Statutes/12-20-39) is distinct from party-primary/runoff electorates. These baselines have one general-election stage; no RCV or runoff preference transfers are inferred.\n',
 'The signed statewide canvasses supply these full candidate fields; every66-county vector sums to its statewide candidate control. The printed2020 order is **Rounds then Ahlers**, visually checked in the [original page derivative](data/baselines/source/visual-senate-2020-column-order.png).\n',
 '| Election / source | Complete named candidate votes and ballot identities | All-candidate denominator | A−B pair margin | A−B all-candidate margin |\n| --- | --- | ---: | ---: | ---: |']
 for y in [2024,2020,2022]:
  rr=[r for r in rows if int(r['year'])==y];a=sum(int(r['a_votes'])for r in rr);b=sum(int(r['b_votes'])for r in rr);n=sum(int(r['all_named_votes'])for r in rr);cc=controls[str(y)];names='; '.join(f'{name} ({party}) {v:,}'for(name,party),v in zip(cc['columns'],cc['candidate_totals']));context={2024:'2024 president',2020:'2020 same-seat Senate',2022:'2022 other-seat Senate / midterm'}[y]
  body.append(f'| [{context}]({news[cc["source_id"]]["url"]}) | {names} | {n:,} | {100*(a-b)/(a+b):+.4f} pp | {100*(a-b)/n:+.4f} pp |')
 body.extend(['\nA is Harris in2024, Ahlers in2020 and **Bengs Democratic on the2022 ballot**. Oliver Libertarian, Kennedy Independent and Lesnar Libertarian remain separate candidates. A−B describes the named pair only. Harris carried5 counties against Trump, Ahlers5 against Rounds and Bengs3 against Thune; those are historical outcomes, not permanent county identities. The [county/candidate table](data/baselines/county-candidates.csv) retains all594 named candidate counts, party labels, printed columns and source positions.\n',
 '**Native evidence and source disagreements.** The actual official history/client/public export chains and complete originals are pinned in the [schema](data/baselines/source/SCHEMA.md) and [asset manifest](data/baselines/asset-manifest.json). The2024 chain is [official history](https://sdsos.gov/elections-voting/election-resources/election-history/2024_Election_History.aspx) → [actual election684](https://electionresults.sd.gov/default.aspx?eid=684) → [published Presidential Electors Precinct Level control](https://electionresults.sd.gov/resultsSW.aspx?type=SWR&map=CTY&eid=684). Original form fields, POST controls and responses remain. The workbook literally says2024 Unofficial General Election Results. All691 rows close their own66 county TOTALs: Harris146811, Oliver2777, Trump271938, Kennedy7202 =428728. Compared with signed totals, differences are **−48/−1/−143/−2=−194 in24 counties**; [every county/candidate difference](data/baselines/native-signed-differences.csv) remains unallocated. A691/691 reporting counter and freshly generated Downloaded at clock do not make those certified votes or establish live cadence.\n',
 'Independently parsed [2022 public Senate export](https://electionresults.sd.gov/resultsSW.aspx?type=SWR&map=CTY&eid=471), discovered through its actual history link and public form, supplies687 native rows/66 parents and matches every signed county/candidate count. It remains source-labeled unofficial. The separately retained [2022 precinct canvass PDF](https://sdsos.gov/elections-voting/assets/Archive/2022%20Assets/2022PrecintCanvass.pdf) has679 rows/65 parents; its66 Senate pages include Minnehaha continuation but **omit Yankton**. Missing PDF native coverage is2462 Bengs/340 Lesnar/6051 Thune, not zero. Yankton’s8 public native rows fill public-source coverage without inventing missing PDF rows or an ID crosswalk. The [recount certificate](https://sdsos.gov/elections-voting/assets/Archive/2022%20Assets/2022GeneralStateCanvassRecountReport.pdf) is District15 House, not new Senate votes to add.\n',
 'The [2020 public Senate export](https://electionresults.sd.gov/resultsSW.aspx?type=SWR&map=CTY&eid=422), independently parsed from its observed history/client/form chain, supplies693 native rows/66 parents: Rounds276208/Ahlers143970=420178. It trails signed controls by **24 Rounds and17 Ahlers votes,41 overall, across21 counties**. Exact county differences and full raw cells are retained. Neither this discrepancy nor2024’s is allocated to native rows. Native names/counts alone establish no cross-year physical equivalence.\n',
 'All four2024 county-canvass PDF groups and the complete2020 county original are retained once, losslessly. Their source page hierarchy and full text remain; scanned OCR is not accepted as image truth. For example [Brookings group page40](data/baselines/source/visual-brookings-2024.png) visibly prints5978/112/8575/274, while OCR contains5974/712/8575/274; [Marshall group page2](data/baselines/source/visual-marshall-2024.png) prints Harris782 while OCR reads742. These images support signed values and do not explain the public workbook deficits. Comprehensive certified native transcription and discrepancy resolution are not claimed. The statewide all-race2024 XLSX separately mislabels D7 as Trump and E7 as Trump1, omitting Oliver; [literal headers/XML](data/baselines/source/candidate-header-presentation.json) are preserved. The admitted native and Aurora workbooks correctly name all four; no candidate is silently relabeled from numerical resemblance.\n',
 'The Census [name/code change notice](https://www.census.gov/programs-surveys/geography/technical-documentation/county-changes.2010.html) identifies Oglala Lakota46102 as the former Shannon46113 effective May1,2015. The used2020/22/24 county sources name Oglala Lakota; it is not a67th county. All worksheet identities, literal administrative/combined/Absentee labels, original positions and missing method cases remain. A place name or VP label is not proof of a precinct, polling site, vote center, municipal parent or VTD geometry. The current setup’s673 overall versus656 Senate units is neither a precinct crosswalk nor actual counted votes.\n',
 '**Turnout and registration controls.** The books’ Votes Cast and active registration denominators are separate from named contest votes. Source dates and every county raw line remain in [turnout-registration-controls.csv](data/baselines/turnout-registration-controls.csv). Native ballots/registration/blank/under/over fields are unavailable, not zero. The difference between Votes Cast and contest votes is unclassified.\n',
 '| Official returns book / turnout PDF page | Votes Cast | Named contest votes | Unclassified difference | Turnout-table registered | Separate active / inactive registration |\n| --- | ---: | ---: | ---: | ---: | ---: |'])
 turn=json.loads((SRC/'turnout-controls.json').read_text())
 for y,page in [(2024,23),(2022,25),(2020,15)]:
  t=turn[str(y)];n=controls[str(y)]['named_total'];url=books[f'returns-{y}-archive']['requested_url'];body.append(f'| [{y} book, p{page}]({url}) | {t["votes_cast"]:,} | {n:,} | {t["votes_cast"]-n:,} | {t["turnout_registered"]:,} | {t["registration_active"]:,} / {t["registration_inactive"]:,} |')
 body.extend(['\nRegistration tables are dated November5,2024 / November8,2022 / November3,2020. Turnout-table registered minus registration-table active is0 / +4 / −11 respectively; county differences remain. These are **historical turnout anchors**, not2026 projections. A separately published2024 terminology page’s registration figure625192 differs from the book624175; it is another source, not a value to normalize into this book. Party registration is not a candidate preference estimate.\n',
 '**Exact source-native concentration.** Independent descending sort uses all four candidate tickets, then ascending county FIPS, numeric worksheet ordinal and source row. [Full native2024 inventory](data/baselines/native-2024.csv) and [complete priority contract](data/baselines/priority-contract.json) retain every691 row, all66 parents and every remaining unit. Top15 provide61003/428728=14.2288%. The smallest source-native prefix reaching80% is304 units:343402/428728=80.0979%;303 provide342947, below the integer target342983. Crossing unit is Hamlin **Precinct-26**, `sd:2024:pres:46057:sheet32:row14`,455 votes. Remaining387 units provide85326 votes.\n',
 'This is explicitly an **unofficial source-native/source-denominator** contract. The signed denominator428922 has ceil80 target343138. The303 source votes are191 short of that, while194 votes remain unallocated in known county scopes. No certified minimum/membership robustness is proved:343402 as an observed source crossing does not approve a certified native priority set. Coordinator acceptance and current geography are external. Separately, signed county concentration reaches80% at21 counties/346205 votes;20 have342469 and top15 counties318769. County concentration is a separate sensitivity, not a replacement for finer native order.\n',
 '**Tie, cushion and feasible paths.** At fixed pair weights, unbounded share shift `(B−A)/(2*(A+B))` ties; A+1 pair-margin needs another0.5 A-share percentage points when nothing clips. Share points, pair-margin points and net votes are separate: a+1 share-point change adds+2 margin points and `.02*pair_volume` net votes. A+1 margin is1% of pair volume, not one vote or1% of all candidate votes. Shares are clipped to[0,1] and the feasible uniform shift is solved again, retaining the unclipped value. Negative/already-winning, no-positive-pool and bounded-impossible cases remain explicit.\n',
 '| Source and full historical weights | Pair votes | Baseline A−B net | Unbounded tie share shift | Feasible clipped tie shift | Feasible A+1 shift | A+1 net cushion / all-candidate margin |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: |'])
 for label,sid in [('Signed2024 counties','county_pref2024_high_mix2024'),('Signed2020 counties','county_pref2020_base_mix2020'),('Signed2022 counties','county_pref2022_low_mix2022'),('Public2024 native691','native_pref2024_observed'),('Public2020 native693','native_pref2020_observed'),('Public2022 native687','native_pref2022_observed')]:
  s=target(sid);c=target(sid,'A_plus_1_pair_margin');body.append(f'| {label} | {s["pair_total"]:,.0f} | {s["baseline_net"]:+,.0f} | {s["unbounded_shift_share_pp"]:+.6f} pp | {s["bounded_shift_share_pp"]:+.6f} pp | {c["bounded_shift_share_pp"]:+.6f} pp | {c["target_net"]:,.2f} / {c["target_all_candidate_margin_pp"]:.6f} pp |')
 body.extend(['\nThe2024 county tie needs14.954311 share points after clipping Oglala Lakota, versus14.945100 unbounded. Native clipping changes the root further because unit weights/preferences differ. Targets in [unit-targets.csv.gz](data/baselines/unit-targets.csv.gz) contain all17756 county/native contributions, pair/all-candidate weights, participation, target shares/margins, net gains and the net-vote value of one share point. Each statewide target reconciles exactly within floating arithmetic tolerance. These are alternative sufficient combinations under fixed assumptions; no county target is individually necessary. A tie is not a win. [State targets](data/baselines/state-targets.json) also retain every historical other candidate and compare full plurality, so pair arithmetic never substitutes for the legal rule.\n',
 'The separate **named2026 Bengs Independent versus Rounds Republican** scenario assumes Bengs repeats one stated historical A pair preference with that scenario’s pair volume, and that only those two current choices receive valid votes. Its all-candidate denominator is then that pair’s volume. Historical Libertarian/Independent shares and candidate-specific effects are not transferred to Bengs; no Democratic2026 choice is fabricated. Historical full-field denominator/cushion results remain alongside this explicitly different named-pair assumption.\n',
 '**Historical low/base/high volume and mix sensitivity.** Low uses actual2022 Senate county all-candidate volumes (348020), base actual2020 same-seat Senate (420219), high actual2024 president (428922). For each historical preference anchor, county pair participation comes from that anchor’s own candidate votes, so scenario pair totals differ. Other candidates retain their own county all-candidate shares. All66 counties remain.\n',
 '| Preference anchor | Volume/mix | Scenario pair volume | Baseline A−B net | Bounded tie share shift | Bounded A+1 share shift |\n| --- | --- | ---: | ---: | ---: | ---: |'])
 for pref in [2024,2020,2022]:
  for level,vol in [('low',2022),('base',2020),('high',2024)]:
   sid=f'county_pref{pref}_{level}_mix{vol}';s=target(sid);c=target(sid,'A_plus_1_pair_margin');body.append(f'| {pref} | {level}: observed{vol} counties | {s["pair_total"]:,.3f} | {s["baseline_net"]:+,.3f} | {s["bounded_shift_share_pp"]:+.6f} pp | {c["bounded_shift_share_pp"]:+.6f} pp |')
 body.extend(['\nThe native low/base/high cases uniformly scale each election’s **own** complete native mix to those historical statewide all-candidate volumes; observed cases keep original votes unchanged. They preserve native pair participation and preferences, changing volume but not composition. This is explicitly sensitivity scaling, not allocation of certified residuals or a cross-year unit join. County-mix effects and native total-only effects are separated in [scenario settings](data/baselines/scenario-settings.json). None establishes2026 turnout, a candidate coalition, reporting method effects or lower preferences.\n',
 '**Selected-unit-only and live remainder.** [Selected-unit-break-even.csv.gz](data/baselines/selected-unit-break-even.csv.gz) solves every county/native unit under each applicable scenario while every other unit stays at its stated historical preference, volume and zero shift. It retains required shares outside0–100%, with impossible/secured status and separate clipped display. [Editable historical input](data/baselines/historical-input-example.json) and the offline calculator allow another explicit elsewhere shift; all66 counties remain fixed except the selected one.\n',
 'The [offline calculator](data/baselines/scripts/calculator.py) keeps all counted A/B/other votes fixed and forecasts only the stated remaining all-candidate pool, candidate by candidate. Remaining pair pool equals remaining total times one minus declared other-candidate shares. Required A share for margin m is `(m*FINAL_pair − counted_net + remaining_pair_pool)/(2*remaining_pair_pool)`. FINAL_pair includes counted pair votes; the final all-candidate denominator also includes all counted and forecast other votes. Selected-only live holds every other remaining contribution fixed. Final plurality compares all declared candidates. No completion flag supplies remaining votes.\n',
 'The [15 synthetic cases](data/baselines/live-synthetic-scenarios.json) cover unknown pool/preference, no pool (tie/won/lost), negative inputs, impossible/secured paths, explicit low/high preference clipping, selected-only fixed elsewhere, a third candidate beating the pair winner, a positive other-only pool, and the FINAL denominator. In the latter case, counted400 Bengs/500 Rounds plus100 remaining pair votes needs105% remaining Bengs share for A+1: target net is10 on final1000, so it is impossible. Replacing that final denominator with remaining100 would be wrong. [Bounded synthetic cases](data/baselines/bounded-synthetic-scenarios.json) separately retain a negative already-winning shift, clipping, a restricted-shift impossible case and no positive pool. These are arithmetic examples, not calibrated probabilities or remaining-vote evidence. Reproduction/CLI commands are in the [schema](data/baselines/source/SCHEMA.md).\n',
 '**Every county, numerical historical outcomes.** This compact table shows all signed county pair margins and full candidate-vote denominators; positive means the named historical A beat B. Complete counts for each candidate, raw rows, party identities and all denominator columns are in [county-baselines.csv](data/county-baselines.csv) and [county-candidates.csv](data/baselines/county-candidates.csv). Sources are the signed2024/2020/2022 canvasses cited above, not a constructed2026 electorate.\n',
 '| County / FIPS | 2024 Harris−Trump pair margin | 2024 all candidates | 2020 Ahlers−Rounds pair margin | 2020 all candidates | 2022 Bengs−Thune pair margin | 2022 all candidates |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: |'])
 for name in sorted({r['county']for r in rows}):
  rr={int(r['year']):r for r in rows if r['county']==name};parts=[f'{name} / {rr[2024]["county_fips"]}']
  for y in [2024,2020,2022]:parts.extend([f'{float(rr[y]["a_minus_b_pair_margin_pp"]):+.3f} pp',f'{int(rr[y]["all_named_votes"]):,}'])
  body.append('| '+' | '.join(parts)+' |')
 body.extend(['\n**Reconciliation and handoff.** The independent originals-first extractor and redirected preflight reproductions reconcile all198 county vectors/594 candidate rows. Full public-native keys/literals/candidates/method scope/source cells/hashes and all691 descending order/304 keys agree with the actual turnout peer; the separate2022 PDF’s679 labels, triples and pages also agree. [Peer reconciliation](data/baselines/peer-reconciliation.json) pins both read-only inputs and711 independent checks. Local keys for2020/22 use a documented source-locator bijection; none is a geography crosswalk.\n',
 'The [validator](data/baselines/validation.json) checks full-state denominators, weights, all-unit contributions, selected-only equations, bounded roots, synthetic final-denominator/plurality cases, exact integer80 crossings, full-field controls, raw originals/ordered parts, owned hashes, links and strict stored-object size bounds. The [complete owned manifest](data/baselines/asset-manifest.json) pins assets and read-only original/source chains. No Git actions or peer/shared file writes were performed.\n',
 'Material qualifications remain precise: public2024 −194 and public2020 −41 are unallocated source-vintage disagreements; certified native priority membership robustness is unproved; original2022 PDF omits Yankton despite complete reconciled public coverage; scanned certified county-native rows are not comprehensively transcribed; direct current publication-ballot PDF bytes could not be downloaded despite successful primary web inspection. Current final operational IDs, approved November geometry, actual remaining-vote assumptions, collector/replay cadence and probability calibration remain external work. Historical targets/calculators are complete and usable offline under their declared assumptions.\n'])
 (DATA.parent/'county-partisanship.md').write_text('\n'.join(body))
